fn fibonacci(n: usize) -> Vec<i32> {
    // According to the problem, n >= 2 and we can safely assume values fit in i32.

    let mut fibs = Vec::with_capacity(n);
    fibs.push(0); // F(0)
    fibs.push(1); // F(1)

    for i in 2..n {
        // Since values are guaranteed to fit in i32, safe to add without overflow.
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}